\set ON_ERROR_STOP on
SET search_path=model_lab,pg_catalog;
BEGIN;
SELECT expect_true('100000 synthetic search documents loaded',(SELECT count(*)=100000 FROM search_documents));
SELECT expect_rejection('Permanent alias cannot be recycled',$s$INSERT INTO aliases VALUES('synthetic','exercise-one',gid(2))$s$,'23505');
SELECT expect_rejection('Alias target cannot be rebound',$s$UPDATE aliases SET exercise_id=gid(2) WHERE external_id='exercise-one'$s$,'55000');
SELECT expect_rejection('Snapshot path uniquely identifies an occurrence',$s$INSERT INTO source_versions VALUES(gid(200001),gid(2),gid(2),'OpenProblemLibrary/Synthetic/revised.pg',repeat('a',64))$s$,'23505');
SELECT expect_rejection('Only one authoritative exercise version per snapshot',$s$INSERT INTO source_versions VALUES(gid(200002),gid(1),gid(2),'OpenProblemLibrary/Synthetic/another.pg',repeat('a',64))$s$,'23505');
SELECT expect_rejection('Repository traversal paths rejected',$s$INSERT INTO source_versions VALUES(gid(200003),gid(2),gid(2),'OpenProblemLibrary/../escape.pg',repeat('a',64))$s$,'23514');
SELECT expect_rejection('Source versions cannot be overwritten',$s$UPDATE source_versions SET sha256=repeat('f',64) WHERE id=gid(1)$s$,'55000');
INSERT INTO source_versions VALUES(gid(100002),gid(2),gid(2),'OpenProblemLibrary/Synthetic/Revised.PG',repeat('a',64));
SELECT expect_true('Linux source path case is preserved',(SELECT count(*)=2 FROM source_versions WHERE snapshot_id=gid(2)));
SELECT expect_true('Identical bytes do not merge exercise identities',(SELECT count(*)=100000 AND count(DISTINCT sha256)=1 FROM source_versions WHERE snapshot_id=gid(1)));
SELECT expect_rejection('Catalog deletion cannot cascade into history',$s$DELETE FROM exercises WHERE id=gid(1)$s$,'23503');
SELECT expect_rejection('Root slugs use NULLS NOT DISTINCT uniqueness',$s$INSERT INTO topic_memberships(release_id,node_id,kind,parent_id,locale,label,slug,position) VALUES(gid(1),gid(3),'subject',NULL,'en','Duplicate','geometry',30)$s$,'23505');
SELECT expect_rejection('Taxonomy parent must have the immediately preceding level',$s$INSERT INTO topic_memberships(release_id,node_id,kind,parent_id,locale,label,slug,position) VALUES(gid(1),gid(23),'section',gid(1),'en','Wrong parent','wrong-parent',30)$s$,'23503');
SELECT expect_true('Sibling slugs may recur under different parents',(SELECT count(*)=2 FROM topic_memberships WHERE slug='vectors'));
SELECT expect_rejection('Exercise assignment must target a section',$s$INSERT INTO topic_assignments VALUES(gid(1),gid(11),'en','section',gid(1),gid(1),gid(1),false)$s$,'23503');
SELECT expect_rejection('At most one primary assignment',$s$UPDATE topic_assignments SET is_primary=true WHERE source_version_id=gid(1) AND node_id=gid(22)$s$,'23505');
SELECT expect_rejection('Deferred check requires a primary when assignments remain',$s$UPDATE topic_assignments SET is_primary=false WHERE source_version_id=gid(1) AND is_primary$s$,'23514');
SELECT expect_true('Cross-list counts deduplicate source exercise identity',(SELECT count(*)=100001 AND count(DISTINCT exercise_id)=100000 FROM topic_assignments));
SELECT expect_rejection('Requirements cannot be borrowed from another source version',$s$INSERT INTO assessments VALUES(gid(200000),gid(1),gid(1),gid(1),gid(1),gid(2),repeat('f',64),'verified')$s$,'23503');
INSERT INTO activation_releases VALUES(gid(2),'synthetic-candidate',gid(1),gid(1),'draft');
SELECT expect_rejection('Failed assessment cannot enter verified publication',$s$INSERT INTO activation_members(release_id,exercise_id,source_version_id,source_snapshot_id,environment_id,profile_id,requirement_set_id,assessment_id) VALUES(gid(2),gid(1),gid(1),gid(1),gid(1),gid(1),gid(1),gid(100001))$s$,'23503');
SELECT expect_rejection('Release member cannot borrow another environment',$s$INSERT INTO activation_members(release_id,exercise_id,source_version_id,source_snapshot_id,environment_id,profile_id,requirement_set_id,assessment_id) VALUES(gid(2),gid(1),gid(1),gid(1),gid(2),gid(1),gid(1),gid(1))$s$,'23503');
WITH changed AS(UPDATE deployment_heads SET generation=generation+1 WHERE scope='synthetic-local' AND generation=0 RETURNING 1) SELECT expect_true('Publication compare-and-swap accepts one expected generation',(SELECT count(*)=1 FROM changed));
WITH changed AS(UPDATE deployment_heads SET generation=generation+1 WHERE scope='synthetic-local' AND generation=0 RETURNING 1) SELECT expect_true('Stale publication generation cannot overwrite head',(SELECT count(*)=0 FROM changed));
UPDATE deployment_heads SET active=false,generation=generation+1 WHERE scope='synthetic-local';
SELECT expect_true('Withdrawal hides discovery without deleting source or evidence',(SELECT count(*)=0 FROM published_catalog) AND (SELECT count(*)=100000 FROM activation_members));
UPDATE deployment_heads SET active=true,generation=generation+1 WHERE scope='synthetic-local';
SELECT expect_rejection('An anonymous principal can be claimed only once',$s$INSERT INTO account_claims(anonymous_principal_id,account_principal_id,state) VALUES(gid(11),gid(22),'active')$s$,'23505');
SELECT expect_rejection('A claim target must be an account principal',$s$INSERT INTO account_claims(anonymous_principal_id,account_principal_id,state) VALUES(gid(12),gid(11),'active')$s$,'23503');
SELECT expect_rejection('A claim cannot be silently reassigned',$s$UPDATE account_claims SET account_principal_id=gid(22) WHERE anonymous_principal_id=gid(11)$s$,'55000');
SELECT expect_true('Owner union includes native and claimed principals only',(SELECT count(*)=2 FROM owned_principals(gid(1))) AND (SELECT count(*)=1 FROM owned_principals(gid(2))));
SELECT expect_true('Claimed bookmarks are deduplicated by exercise',(SELECT count(DISTINCT exercise_id)=1 FROM bookmarks WHERE owner_id IN(SELECT owner_id FROM owned_principals(gid(1)))));
UPDATE principals SET state='disabled' WHERE id=gid(21);
SELECT expect_true('Disabling account principal removes claimed union access',(SELECT count(*)=0 FROM owned_principals(gid(1))));
UPDATE principals SET state='active' WHERE id=gid(21);
SELECT expect_rejection('Pinned sessions require explicit source and environment',$s$INSERT INTO sessions(id,owner_id,exercise_id,binding) VALUES(gid(300000),gid(21),gid(1),'pinned')$s$,'23514');
SELECT expect_rejection('Session source and environment snapshots must agree',$s$INSERT INTO sessions(id,owner_id,exercise_id,binding,source_version_id,environment_id,snapshot_id) VALUES(gid(300001),gid(21),gid(1),'pinned',gid(1),gid(2),gid(1))$s$,'23503');
SELECT expect_rejection('Practice item cannot reference another student session',$s$INSERT INTO practice_items VALUES(gid(1),gid(21),3,gid(1),gid(1),gid(1),gid(1),gid(2))$s$,'23503');
SELECT expect_rejection('Draft owner must match session owner',$s$INSERT INTO drafts VALUES(gid(2),gid(1),gid(22),'wrong-owner',0,NULL,'[]')$s$,'23503');
SELECT expect_rejection('Last-attempt pointer must refer to the same owned session',$s$UPDATE sessions SET last_attempt_id=gid(1) WHERE id=gid(2)$s$,'23503');
SELECT expect_rejection('Idempotency key is unique within the session',$s$INSERT INTO submission_operations VALUES(gid(3),gid(1),gid(21),'synthetic-operation-one',repeat('c',64),0,'queued')$s$,'23505');
INSERT INTO submission_operations VALUES(gid(3),gid(1),gid(21),'synthetic-active',repeat('c',64),2,'uncertain');
SELECT expect_rejection('Uncertain operation fences another submission',$s$INSERT INTO submission_operations VALUES(gid(4),gid(1),gid(21),'synthetic-next',repeat('d',64),2,'queued')$s$,'23505');
SELECT expect_rejection('An uncertain operation cannot be an accepted attempt',$s$INSERT INTO attempts(id,session_id,owner_id,binding,exercise_id,source_version_id,environment_id,operation_id,ordinal,provenance,feedback_visibility,score,answers) VALUES(gid(4),gid(1),gid(21),'pinned',gid(1),gid(1),gid(1),gid(3),3,'server-pg','shown',1,'[]')$s$,'23503');
SELECT expect_rejection('Legacy nullable binding cannot bypass parent exercise identity',$s$INSERT INTO attempts(id,session_id,owner_id,binding,exercise_id,ordinal,provenance,feedback_visibility,score,answers) VALUES(gid(5),gid(3),gid(21),'legacy-unbound',gid(2),2,'legacy-client','shown',1,'[]')$s$,'23503');
SELECT expect_rejection('Accepted attempt cannot be edited',$s$UPDATE attempts SET score=1 WHERE id=gid(1)$s$,'55000');
SELECT expect_true('JSON arrays retain repeated answer names and whitespace',(SELECT answers->0->>1=' first ' AND answers->0->>0=answers->1->>0 FROM attempts WHERE id=gid(1)));
SELECT expect_true('Malformed ordered answer-pair payloads rejected',NOT valid_pairs('{"a":"b"}') AND NOT valid_pairs('[["a",7]]') AND valid_pairs('[["a","x"],["a","y"]]'));
WITH changed AS(UPDATE drafts d SET revision=d.revision+1 FROM sessions s WHERE d.id=gid(1) AND d.session_id=s.id AND d.owner_id=s.owner_id AND d.revision=0 AND s.last_attempt_id IS NOT DISTINCT FROM gid(1) RETURNING 1) SELECT expect_true('Stale checked baseline cannot save draft',(SELECT count(*)=0 FROM changed));
SELECT expect_true('Unknown or suppressed grades do not earn visible correctness',(SELECT count(*)=0 FROM attempts WHERE owner_id=gid(21) AND provenance='server-pg' AND binding='pinned' AND feedback_visibility='shown' AND score=1));
SELECT expect_true('Public browser role can select only the safe catalog projection',has_table_privilege('model_lab_browser','model_lab.published_catalog','SELECT') AND NOT has_table_privilege('model_lab_browser','model_lab.renderer_state','SELECT') AND NOT has_table_privilege('model_lab_browser','model_lab.attempts','SELECT'));
SELECT expect_true('Scalar-product synonym uses approved metadata',(SELECT count(*)=1 FROM published_catalog WHERE document @@ prefix_query('SCALAR PRO')));
SELECT expect_true('Every search token must match',(SELECT count(*)=0 FROM published_catalog WHERE document @@ prefix_query('scalar matrix')));
SELECT expect_rejection('Search query budget is enforced',$s$SELECT prefix_query(repeat('x',161))$s$,'22023');
SELECT expect_true('Browse keyset has no duplicate boundary row',(WITH first_page AS(SELECT exercise_id,title_sort FROM published_catalog WHERE locale='en' ORDER BY title_sort,exercise_id LIMIT 20),boundary AS(SELECT * FROM first_page ORDER BY title_sort DESC,exercise_id DESC LIMIT 1),next_page AS(SELECT d.exercise_id FROM published_catalog d,boundary b WHERE d.locale='en' AND(d.title_sort,d.exercise_id)>(b.title_sort,b.exercise_id) ORDER BY d.title_sort,d.exercise_id LIMIT 20) SELECT NOT EXISTS(SELECT 1 FROM first_page JOIN next_page USING(exercise_id))));
SELECT expect_true('Browser role cannot call the account-owner resolver',NOT has_function_privilege('model_lab_browser','model_lab.owned_principals(uuid)','EXECUTE'));
SELECT expect_rejection('Deleting a claim cannot revive anonymous authority',$s$DELETE FROM account_claims WHERE anonymous_principal_id=gid(11)$s$,'55000');
SELECT expect_rejection('A session owner cannot be rebound even with a known account ID',$s$UPDATE sessions SET owner_id=gid(22) WHERE id=gid(1)$s$,'55000');
SELECT expect_rejection('A started practice item cannot silently lose its session',$s$UPDATE practice_items SET session_id=NULL WHERE set_id=gid(1) AND position=1$s$,'55000');
SELECT expect_rejection('Unbound legacy history cannot be labeled new pinned PG proof',$s$INSERT INTO attempts(id,session_id,owner_id,binding,exercise_id,operation_id,ordinal,provenance,feedback_visibility,score,answers) VALUES(gid(90),gid(3),gid(21),'legacy-unbound',gid(1),gid(1),2,'server-pg','shown',1,'[]')$s$,'23514');
SELECT expect_rejection('Blank legacy aliases cannot be registered',$s$INSERT INTO aliases VALUES('synthetic','',gid(2))$s$,'23514');
COMMIT;
ANALYZE;
